<template><div class="login-page">
  <header><div class="brand"><span class="brand-mark"><i/><i/><i/></span><b>TestPilot AI</b></div><LanguageSwitcher/></header>
  <main>
    <section class="product-story"><div class="eyebrow">AI QA EXECUTION PLATFORM</div><h1>{{t('auth.heroTitle')}}</h1><p>{{t('auth.heroDesc')}}</p>
      <div class="run-preview"><div class="preview-head"><span><i/>T-102 · AUTHENTICATION TEST</span><b>RUNNING</b></div><div class="flow"><div class="done"><span>01</span><p>{{t('auth.previewPlan')}}</p><b>✓</b></div><div class="done"><span>02</span><p>{{t('auth.previewExecute')}}</p><b>✓</b></div><div class="active"><span>03</span><p>{{t('auth.previewAnalyze')}}</p><b>●</b></div><div><span>04</span><p>{{t('auth.previewReport')}}</p><b>○</b></div></div><div class="evidence"><span>POST /api/auth/login</span><b>500 ERROR</b><em>216 ms</em><p>{{t('auth.previewEvidence')}}</p></div></div>
      <div class="trust"><span><b>TRACE</b>{{t('auth.traceValue')}}</span><span><b>EVIDENCE</b>{{t('auth.evidenceValue')}}</span><span><b>SELF-HEALING</b>{{t('auth.healingValue')}}</span></div>
    </section>
    <section class="access-panel"><div><span class="access-label">{{isRegister?t('auth.createAccount'):t('auth.workspaceAccess')}}</span><h2>{{isRegister?t('auth.register'):t('auth.welcome')}}</h2><p>{{isRegister?t('auth.registerHint'):t('auth.loginHint')}}</p></div>
      <el-form :model="form" @submit.prevent="handleSubmit" label-position="top"><el-form-item :label="t('auth.username')"><el-input v-model="form.username" placeholder="admin"/></el-form-item><el-form-item v-if="isRegister" :label="t('auth.displayName')"><el-input v-model="form.displayName"/></el-form-item><el-form-item v-if="isRegister" :label="t('auth.email')"><el-input v-model="form.email" placeholder="you@example.com"/></el-form-item><el-form-item :label="t('auth.password')"><el-input v-model="form.password" type="password" placeholder="••••••" show-password/></el-form-item><button type="submit" class="primary-btn" :disabled="loading">{{loading?t('common.loading'):(isRegister?t('auth.register'):t('auth.login'))}}</button></el-form>
      <div class="divider"><span>{{t('auth.or')}}</span></div><button class="demo-btn" @click="enterDemo"><span>▶</span><div><b>{{t('auth.enterDemo')}}</b><small>{{t('auth.demoHint')}}</small></div><em>→</em></button>
      <button class="switch" @click="isRegister=!isRegister">{{isRegister?t('auth.switchLogin'):t('auth.switchRegister')}}</button><footer>{{t('auth.localNotice')}}</footer>
    </section>
  </main>
</div></template>
<script setup lang="ts">
import { ref } from 'vue';import { useI18n } from 'vue-i18n';import { useRouter } from 'vue-router';import { ElMessage } from 'element-plus/es/components/message/index.mjs';import { authApi } from '@/api';import LanguageSwitcher from '@/components/common/LanguageSwitcher.vue'
const {t}=useI18n(),router=useRouter();const loading=ref(false),isRegister=ref(false),form=ref({username:'',password:'',displayName:'',email:''})
function enterDemo(){localStorage.setItem('accessToken','testpilot-showcase');localStorage.setItem('user',JSON.stringify({id:1,username:'demo',displayName:'Demo User'}));router.push({path:'/workspace',query:{tour:'1'}})}
async function handleSubmit(){if(!form.value.username||!form.value.password){ElMessage.warning(t('auth.fillFields'));return}loading.value=true;try{if(isRegister.value){await authApi.register(form.value);ElMessage.success(t('auth.registerSuccess'));isRegister.value=false}else{const res=await authApi.login({username:form.value.username,password:form.value.password});localStorage.setItem('accessToken',res.data.accessToken);localStorage.setItem('user',JSON.stringify(res.data.user));ElMessage.success(t('auth.loginSuccess'));router.push('/workspace')}}catch(e:any){ElMessage.error(e.response?.data?.message||t('auth.loginFailed'))}finally{loading.value=false}}
</script>
