e-columns:repeat(4,1fr);padding:15px 12px}.flow>div{display:grid;grid-template-columns:20px 1fr 15px;gap:5px;padding:4px 8px;border-right:1px solid var(--border-subtle);color:var(--text-muted);font-size:10px}.flow>div:last-child{border:0}.flow span{font:9px var(--font-mono)}.flow b{font-weight:400}.flow .done{color:var(--success)}.flow .done p{color:var(--text-secondary)}.flow .active{color:var(--info)}.flow .active p{color:var(--text-primary)}.evidence{display:grid;grid-template-columns:1fr 90px 60px;gap:10px;padding:12px;border-top:1px solid var(--border-subtle);font:10px var(--font-mono)}.evidence>b{color:var(--danger)}.evidence>em{color:var(--text-muted)}.evidence>p{grid-column:1/-1;color:var(--text-secondary);font-family:var(--font-sans)}.trust{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;margin-top:25px}.trust span{display:grid;gap:5px;color:var(--text-muted);font-size:10px}.trust b{color:var(--text-secondary);font:9px var(--font-mono)}.access-panel{display:flex;flex-direction:column;justify-content:center;width:100%;max-width:440px;padding:48px clamp(34px,5vw,68px)}.access-label{color:var(--primary);font:9px var(--font-mono);letter-spacing:.08em}.access-panel h2{margin:8px 0 5px;font-size:21px}.access-panel>div:first-child p{margin-bottom:24px;color:var(--text-muted);font-size:11px}.primary-btn{width:100%;height:36px;border:0;border-radius:6px;background:var(--primary);color:#081018;font-weight:600;cursor:pointer}.primary-btn:hover{background:var(--primary-hover)}.divider{display:flex;align-items:center;gap:10px;margin:17px 0;color:var(--text-muted);font-size:9px}.divider:before,.divider:after{content:'';height:1px;flex:1;background:var(--border-subtle)}.demo-btn{display:grid;grid-template-columns:28px 1fr 16px;align-items:center;gap:9px;width:100%;padding:10px;border:1px solid var(--border-active);border-radius:6px;background:var(--bg-surface);color:var(--text-primary);text-align:left;cursor:pointer}.demo-btn:hover{background:var(--bg-hover);bor